// @name Solitaire
// @background #2f5a48
// @refresh 3600
// Klondike solitaire for a touch screen. Tap a card to pick it up (with the
// cards on it), then tap where it goes; tap it twice to send it home (its
// foundation, else a column that takes it). Tap the stock to draw. Undo goes
// back as far as you like. The game in progress is kept on the frame. A won
// game ends in the cascade of Windows solitaire (cascade.ts).
import { deal, move, autoTarget, drawStock, won, canFinish, finish, cardsAt } from './logic'
import { startCascade, stepCascade, cascadeDone, sampleCascade, stepsUntilCard, pileTop } from './cascade'
import { Face, Back, Place } from './cards'
import { highContrast, canvasOf, Button, OptionsPage, roundOf } from './ui'

const THEMES = {
  color: {
    page: 'bg-[#2f5a48] text-white',
    felt: '#2f5a48',
    muted: 'text-[#cfe0d6]',
    button: 'bg-[#244a3a] text-white active:bg-[#1c3b2e]',
    primary: 'bg-[#e8b33a] text-[#1f2933] active:bg-[#f0c45a]',
    on: 'bg-[#e8b33a] text-[#1f2933]',
    off: 'bg-[#244a3a] text-white',
    banner: 'bg-[#fffdf8] text-[#1f2933]',
    card: '#fffdf8',
    cardEdge: '#b9b2a2',
    red: '#b8432f',
    black: '#1f2933',
    hollowRed: false,
    lit: '#e8b33a',
    back: '#1f3a5f',
    backEdge: '#16294a',
    backLine: '#5b7aa6',
    slot: '#2a5141',
    slotEdge: '#4d7a66',
    slotMark: '#6e9a85',
    faint: { red: '#3f6b58', black: '#3f6b58', hollowRed: false },
  },
  high: {
    page: 'bg-white text-black',
    felt: '#ffffff',
    muted: 'text-black',
    button: 'bg-white text-black border-2 border-black',
    primary: 'bg-black text-white',
    on: 'bg-black text-white',
    off: 'bg-white text-black border-2 border-black',
    banner: 'bg-white text-black border-4 border-black',
    card: '#ffffff',
    cardEdge: '#000000',
    red: '#000000',
    black: '#000000',
    hollowRed: true,
    lit: '#000000',
    back: '#000000',
    backEdge: '#000000',
    backLine: '#ffffff',
    slot: '#ffffff',
    slotEdge: '#000000',
    slotMark: '#000000',
    faint: { red: '#000000', black: '#000000', hollowRed: true },
  },
}

const drawOf = (app) => (String(app.state.draw) === '3' ? 3 : 1)

// The game in progress, kept in the scene's private `game` field, with the
// positions before each move (as text) for undo.
const loadGame = (app) => {
  const g = app.state.game
  return g && Array.isArray(g.tab) && g.tab.length === 7 && Array.isArray(g.found) ? g : null
}
const save = (game) => frameos.setState('game', game)
const snapshot = (game) => JSON.stringify({ ...game, undo: undefined })

// What a tap changes is signals: each column, each foundation, the stock and
// the waste, and the moves. A tap runs only the components that read them,
// not get(). A tap that wins sets none: the cascade is get()'s.
const columns = [0, 1, 2, 3, 4, 5, 6].map(() => signal({ cards: [], down: 0, lit: 99 }))
const foundations = [0, 1, 2, 3].map(() => signal({ top: -1, lit: false }))
const stockWaste = signal({ stock: false, waste: [], again: false, lit: false })
const status = signal({ moves: 0, finishable: false })
// The game get() last loaded (a tap plays on it) and the app it ran with.
let game = null
let lastApp = null

// A signal set to what it holds already wakes nothing.
const show = (s, value) => {
  if (JSON.stringify(s.peek()) !== JSON.stringify(value)) s.value = value
}
const sync = () => {
  if (won(game)) return
  const sel = frameos.recall('sel')
  game.tab.forEach((cards, col) => {
    // A copy: a move changes the game's columns in place.
    show(columns[col], { cards: cards.slice(), down: game.down[col], lit: sel && sel.pile === 'tab' && sel.col === col ? sel.index : 99 })
  })
  game.found.forEach((pile, k) => {
    show(foundations[k], { top: pile.length ? pile[pile.length - 1] : -1, lit: !!(sel && sel.pile === 'found' && sel.col === k) })
  })
  show(stockWaste, {
    stock: game.stock.length > 0,
    waste: game.waste.slice(-Math.max(1, game.draw)),
    again: game.waste.length > 0,
    lit: !!(sel && sel.pile === 'waste'),
  })
  show(status, { moves: game.moves, finishable: canFinish(game) })
}

// Runs `change` on the game; when it changes something, the position before
// goes on the undo list (the last 40) and the game is saved.
const play = (change: (game) => boolean) => {
  if (!game) return false
  const before = snapshot(game)
  if (!change(game)) return false
  game.undo = [...(game.undo || []).slice(-39), before]
  save(game)
  return true
}

const undo = () => {
  if (!game || !game.undo || !game.undo.length) return
  const undoList = game.undo.slice(0, -1)
  const previous = JSON.parse(game.undo[game.undo.length - 1])
  game = { ...previous, undo: undoList }
  save(game)
  frameos.remember('sel', null)
  sync()
}

const restart = (app) => {
  save(deal(drawOf(app), Math.random))
  frameos.remember('sel', null)
  frameos.remember('page', null)
  frameos.remember('win', null)
}
const restartLast = () => restart(lastApp)

const finishAll = () => {
  play((g) => {
    finish(g)
    return true
  })
  sync()
}

const same = (a, b) => a && b && a.pile === b.pile && a.col === b.col && a.index === b.index

// A tap on a card or a place. `from` is the card tapped (null for an empty
// place or the space under a column), `to` where a held card would go.
const tap = (from, to) => {
  if (!game || won(game)) return
  const sel = frameos.recall('sel')
  if (sel) {
    // The same card again: send it home.
    if (same(sel, from)) {
      const target = autoTarget(game, sel)
      if (target) play((g) => move(g, sel, target))
      frameos.remember('sel', null)
      sync()
      return
    }
    if (to && play((g) => move(g, sel, to))) {
      frameos.remember('sel', null)
      sync()
      return
    }
  }
  frameos.remember('sel', from && cardsAt(game, from).length ? from : null)
  sync()
}

const tapStock = () => {
  frameos.remember('sel', null)
  play(drawStock)
  sync()
}

// Frames with buttons: forward draws from the stock, back is undo. On a
// keyboard: space draws, U undoes, N deals again.
export function onEvent(app, context) {
  const event = context.event
  game = loadGame(app)
  lastApp = app
  if (game && won(game) && (event === 'forward' || (event === 'keyDown' && [' ', 'enter'].includes(String(context.payload?.key || '').toLowerCase())))) {
    tapWin(app)
    return true
  }
  if (event === 'forward') tapStock()
  else if (event === 'back') undo()
  else if (event === 'keyDown') {
    const p = context.payload || {}
    if (p.ctrl || p.alt || p.meta) return false
    const key = String(p.key || '').toLowerCase()
    if (key === ' ') tapStock()
    else if (key === 'u' || key === 'backspace') undo()
    else if (key === 'n') restart(app)
    else return false
  } else return false
  return true
}

// Where each card of a column sits, from the top of the column: face-down
// cards closer together than face-up ones, and all of them closer when the
// column would run off the bottom.
const columnOffsets = (count: number, down: number, cardH: number, height: number) => {
  const downStep = cardH * 0.13
  const upStep = cardH * 0.3
  const up = count - down
  const need = down * downStep + Math.max(0, up - 1) * upStep
  const scale = need > 0 ? Math.min(1, (height - cardH) / need) : 1
  const ys: number[] = []
  let y = 0
  for (let i = 0; i < count; i++) {
    ys.push(y)
    y += (i < down ? downStep : upStep) * scale
  }
  return ys
}

// One column, `x` across the table.
const Column = memo(({ t, col, x, cardW, cardH, height }) => {
  const { cards, down, lit } = columns[col].value
  if (!cards.length) return <Place t={t} x={x} y={0} w={cardW} h={cardH} />
  const offsets = columnOffsets(cards.length, down, cardH, height)
  return (
    <g>
      {cards.map((card, i) => (i < down
        ? <Back t={t} x={x} y={offsets[i]} w={cardW} h={cardH} />
        : <Face t={t} card={card} x={x} y={offsets[i]} w={cardW} h={cardH} full={i === cards.length - 1} lit={i >= lit} />))}
    </g>
  )
})

// The seven columns as one drawing, `cardW` cards with `gap` between, and the
// tap that finds the card under the finger.
const Tableau = ({ t, cardW, cardH, gap, height }) => {
  const width = cardW * 7 + gap * 6
  const parts = []
  for (let col = 0; col < 7; col++) parts.push(<Column t={t} col={col} x={col * (cardW + gap)} cardW={cardW} cardH={cardH} height={height} />)
  return (
    <div className={`w-[${width}px] h-[${height}px] shrink-0`}
      onClick={(e) => {
        const col = Math.floor((e.localX / e.width) * width / (cardW + gap))
        if (col < 0 || col > 6 || !game) return
        const column = game.tab[col]
        const offsets = columnOffsets(column.length, game.down[col], cardH, height)
        const y = (e.localY / e.height) * height
        let index = -1
        for (let i = column.length - 1; i >= 0; i--) {
          if (y >= offsets[i]) {
            index = i === column.length - 1 && y > offsets[i] + cardH ? -1 : i
            break
          }
        }
        const from = index >= game.down[col] ? { pile: 'tab', col, index } : null
        tap(from, { pile: 'tab', col })
      }}>
      <svg viewBox={`0 0 ${width} ${height}`} width={width} height={height}>{parts}</svg>
    </div>
  )
}

// Foundation `k`: its top card, or its place.
const Foundation = memo(({ t, k, x, y, cardW, cardH }) => {
  const { top, lit } = foundations[k].value
  return top >= 0
    ? <Face t={t} card={top} x={x} y={y} w={cardW} h={cardH} full={true} lit={lit} />
    : <Place t={t} x={x} y={y} w={cardW} h={cardH} suit={k} />
})

// The foundations, `vertical` in a column or in a row, or `cols` across
// (two: two by two), the top card of each.
const Foundations = ({ t, cardW, cardH, gap, vertical, cols = vertical ? 1 : 4 }) => {
  const rows = 4 / cols
  const width = cardW * cols + gap * (cols - 1)
  const height = cardH * rows + gap * (rows - 1)
  const parts = []
  for (let k = 0; k < 4; k++) {
    parts.push(<Foundation t={t} k={k} x={(k % cols) * (cardW + gap)} y={Math.floor(k / cols) * (cardH + gap)} cardW={cardW} cardH={cardH} />)
  }
  return (
    <div className={`w-[${width}px] h-[${height}px] shrink-0`}
      onClick={(e) => {
        const col = Math.min(cols - 1, Math.floor(((e.localX / e.width) * width) / (cardW + gap)))
        const row = Math.min(rows - 1, Math.floor(((e.localY / e.height) * height) / (cardH + gap)))
        const k = row * cols + col
        if (game) tap(game.found[k].length ? { pile: 'found', col: k } : null, { pile: 'found', col: k })
      }}>
      <svg viewBox={`0 0 ${width} ${height}`} width={width} height={height}>{parts}</svg>
    </div>
  )
}

// The stock and the top of the waste (its top three fanned when drawing three).
const StockCards = memo(({ t, cardW, cardH, gap, vertical, fan }) => {
  const { stock, waste, again, lit } = stockWaste.value
  const wx = vertical ? 0 : cardW + gap
  const wy = vertical ? cardH + gap : 0
  return (
    <g>
      {stock ? <Back t={t} x={0} y={0} w={cardW} h={cardH} /> : <Place t={t} x={0} y={0} w={cardW} h={cardH} mark={again ? 'again' : ''} />}
      {waste.length ? null : <Place t={t} x={wx} y={wy} w={cardW} h={cardH} />}
      {waste.map((card, i) => {
        const last = i === waste.length - 1
        return (
          <Face t={t} card={card} x={wx + (vertical ? 0 : fan * i)} y={wy + (vertical ? fan * i : 0)} w={cardW} h={cardH}
            full={last} lit={last && lit} />
        )
      })}
    </g>
  )
})

// The stock and the waste, one under the other or side by side.
const StockWaste = ({ t, draw, cardW, cardH, gap, vertical }) => {
  const fan = draw === 3 ? (vertical ? cardH * 0.2 : cardW * 0.25) : 0
  const width = vertical ? cardW : cardW * 2 + gap + fan * 2
  const height = vertical ? cardH * 2 + gap + fan * 2 : cardH
  return (
    <div className={`w-[${width}px] h-[${height}px] shrink-0`}
      onClick={(e) => {
        const along = vertical ? (e.localY / e.height) * height : (e.localX / e.width) * width
        if (along < (vertical ? cardH : cardW)) tapStock()
        else if (along > (vertical ? cardH : cardW) + gap) tap({ pile: 'waste' }, null)
      }}>
      <svg viewBox={`0 0 ${width} ${height}`} width={width} height={height}>
        <StockCards t={t} cardW={cardW} cardH={cardH} gap={gap} vertical={vertical} fan={fan} />
      </svg>
    </div>
  )
}

// A wide screen's left column under the stock and the waste (a strip's own
// column, `cardW` wide): the moves and the buttons.
const SideButtons = memo(({ ui, t, cardW, gap }) => {
  const { moves, finishable } = status.value
  const buttonH = Math.max(44, Math.round(cardW * 0.55))
  const small = `h-[${buttonH}px] w-full rounded-lg flex items-center justify-center text-[${Math.round(Math.min(ui.small, cardW / 4.6))}px] font-semibold`
  return (
    <div className={`w-full flex flex-col gap-[${gap}px]`}>
      <span className={`text-[${Math.round(Math.min(ui.small, cardW / 4.2))}px] text-center ${t.muted}`}>{`${moves} ${moves === 1 ? 'move' : 'moves'}`}</span>
      {finishable ? <div className={`${small} ${t.primary}`} onClick={finishAll}>Finish</div> : null}
      <div className={`${small} ${t.button}`} onClick={undo}>Undo</div>
      <div className={`${small} ${t.button}`} onClick={restartLast}>New</div>
      <div className={`${small} ${t.button}`} onClick={showOptions}>Options</div>
    </div>
  )
})

// The classic table's row under the columns: the moves and the buttons.
const ButtonRow = memo(({ ui, t, width, gap }) => {
  const { moves, finishable } = status.value
  return (
    <div className={`flex items-center w-[${width}px] gap-[${gap}px]`}>
      <span className={`flex-1 text-[${ui.small}px] ${t.muted}`}>{`${moves} ${moves === 1 ? 'move' : 'moves'}`}</span>
      {finishable ? <Button ui={ui} grow className={t.primary} onClick={finishAll}>Finish</Button> : null}
      <Button ui={ui} className={t.button} onClick={undo}>Undo</Button>
      <Button ui={ui} className={t.button} onClick={restartLast}>New</Button>
      <Button ui={ui} className={t.button} onClick={showOptions}>Options</Button>
    </div>
  )
})

const showOptions = () => frameos.remember('page', 'options')

// Round: the moves in the arc above the table.
const RoundMoves = memo(({ ui, t }) => {
  const { moves } = status.value
  return <span className={`text-[${ui.small}px] ${t.muted}`}>{`${moves} ${moves === 1 ? 'move' : 'moves'}`}</span>
})

// Round: Undo, New (Finish when the rest can go home by itself) and Options
// in the arc below the table, `width` across all three.
const RoundButtons = memo(({ ui, t, width, h, gap }) => {
  const { finishable } = status.value
  const w = Math.floor((width - gap * 2) / 3)
  const pill = `w-[${w}px] h-[${h}px] rounded-full flex items-center justify-center text-[${ui.small}px] font-semibold`
  return (
    <div className={`flex gap-[${gap}px]`}>
      <div className={`${pill} ${t.button}`} onClick={undo}>Undo</div>
      {finishable
        ? <div className={`${pill} ${t.primary}`} onClick={finishAll}>Finish</div>
        : <div className={`${pill} ${t.button}`} onClick={restartLast}>New</div>}
      <div className={`${pill} ${t.button}`} onClick={showOptions}>Options</div>
    </div>
  )
})

// Round: the classic table in the band across the circle's middle, wider
// than the square inside it: seven cards across 82% of the circle, the rows
// as tall as that width allows.
const roundTableOf = (room, gap: number) => {
  const cardW = Math.floor((room.r * 1.64 - gap * 6) / 7)
  const cardH = Math.round(cardW * 1.4)
  const tableW = cardW * 7 + gap * 6
  const half = Math.floor(Math.sqrt(room.r * room.r - (tableW / 2) * (tableW / 2)))
  return { cardW, cardH, tableW, x0: Math.round((room.W - tableW) / 2), top: Math.round(room.H / 2) - half, bottom: Math.round(room.H / 2) + half }
}

// The cards' size and the layout (below in get()). A wide screen: the stock
// and the waste on the left with the buttons under them, the columns, the
// foundations on the right, where a card is wide enough for the buttons'
// words under the stock. A strip too short for that (a 792x272 panel): the
// foundations two by two and the buttons in a column of their own, when that
// gives bigger cards than the classic table. Every other screen: the classic
// table, the stock and the foundations along the top, the buttons under it.
const SIDE_CARD = 56
const stripColumnOf = (ui) => Math.max(64, Math.ceil(ui.small * 4.8))
const sizesOf = (ui, gap: number) => {
  const sized = (mode: string, w: number) => {
    const cardW = Math.floor(w)
    return { mode, wide: mode !== 'classic', cardW, cardH: Math.round(cardW * 1.4) }
  }
  const classic = Math.min((ui.W - ui.pad * 2 - gap * 6) / 7, ((ui.H - ui.pad * 2 - ui.button - gap * 2) * 0.3) / 1.4)
  if (ui.W >= ui.H * 1.3) {
    const wide = Math.min((ui.W - ui.pad * 2 - gap * 8) / 9, (ui.H - ui.pad * 2 - gap * 3) / 4 / 1.4)
    if (wide >= SIDE_CARD) return sized('wide', wide)
    // Two cards and the waste's fan of three under each other, and beside
    // them the columns, the foundations two across and the buttons.
    const strip = Math.min((ui.W - ui.pad * 2 - stripColumnOf(ui) - gap * 9) / 10, (ui.H - ui.pad * 2 - gap) / 2.4 / 1.4)
    if (Math.floor(strip) > Math.floor(classic)) return sized('strip', strip)
  }
  return sized('classic', classic)
}

// Where get()'s layouts put the piles, in the UI's pixels: the four
// foundations, and the stock, the waste and the seven columns.
const tableOf = (ui, gap: number, room = null) => {
  if (room) {
    const { cardW, cardH, x0, top } = roundTableOf(room, gap)
    const step = cardW + gap
    return {
      cardW,
      cardH,
      piles: [0, 1, 2, 3].map((k) => ({ x: x0 + step * (3 + k), y: top })),
      places: [{ x: x0, y: top }, { x: x0 + step, y: top }, ...[0, 1, 2, 3, 4, 5, 6].map((col) => ({ x: x0 + step * col, y: top + cardH + gap }))],
    }
  }
  const { mode, wide, cardW, cardH } = sizesOf(ui, gap)
  const step = cardW + gap
  const tableW = cardW * 7 + gap * 6
  if (wide) {
    const strip = mode === 'strip'
    const x0 = ui.pad + (ui.W - ui.pad * 2 - (strip ? cardW * 10 + gap * 9 + stripColumnOf(ui) : cardW * 9 + gap * 8)) / 2
    const fx = x0 + step * 8
    return {
      cardW,
      cardH,
      piles: [0, 1, 2, 3].map((k) => (strip
        ? { x: fx + (k % 2) * step, y: ui.pad + Math.floor(k / 2) * (cardH + gap) }
        : { x: fx, y: ui.pad + k * (cardH + gap) })),
      places: [{ x: x0, y: ui.pad }, { x: x0, y: ui.pad + cardH + gap }, ...[0, 1, 2, 3, 4, 5, 6].map((col) => ({ x: x0 + step * (col + 1), y: ui.pad }))],
    }
  }
  const x0 = (ui.W - tableW) / 2
  return {
    cardW,
    cardH,
    piles: [0, 1, 2, 3].map((k) => ({ x: x0 + step * (3 + k), y: ui.pad })),
    places: [{ x: x0, y: ui.pad }, { x: x0 + step, y: ui.pad }, ...[0, 1, 2, 3, 4, 5, 6].map((col) => ({ x: x0 + step * col, y: ui.pad + cardH + gap }))],
  }
}

// The cascade's pace on a fast panel: STEPS copies of the card a frame, a
// frame every PACE seconds. The scene's interval is its private `pace` field
// (role refreshInterval), so the frame renders this often only while cards
// fall and goes back to an hour after: an ESP32's LCD animates (a scene below
// a second does) for the cascade alone.
const STEPS = 5
const PACE = 0.04
const IDLE = 3600
// E-paper draws one picture: the cascade once the four kings have gone, in at
// most PAPER_COPIES copies of the cards. A canvas made again in the middle
// of a cascade gets the cascade so far in REDRAW_COPIES.
const PAPER_CARD = 4
const PAPER_COPIES = 150
const REDRAW_COPIES = 120

const setPace = (app, seconds: number) => {
  if (Number(app.state.pace) !== seconds) frameos.setState('pace', seconds)
}

// Each won game has its own cascade, the same every time it is drawn.
const seedOf = (game) => (Math.imul(game.moves + 1, 0x9e3779b1) ^ 0x5bd1e995) | 0

// The cascade under way, kept between renders: { moves, seed, c, over }.
const cascadeOf = (game) => {
  const kept = frameos.recall('win')
  if (kept && kept.moves === game.moves && kept.c) return kept
  const seed = seedOf(game)
  return { moves: game.moves, seed, c: startCascade(seed), over: false }
}

// A tap while the cards fall stops them; once they have stopped, a tap deals
// again.
const tapWin = (app) => {
  const game = loadGame(app)
  if (!game) return
  const win = cascadeOf(game)
  if (app.frame.fast && !win.over) frameos.remember('win', { ...win, over: true })
  else restart(app)
}

// Back in a game (dealt or undone, the cascade stopped or not): an hour
// between renders again, and the canvas the cascade drew in, the size of the
// screen, made one pixel, which lets the big one go (an app cannot free one).
const letCascadeGo = (app) => {
  setPace(app, IDLE)
  if (!frameos.recall('cascadeCanvas')) return
  frameos.canvas('cascade', 1, 1)
  frameos.remember('cascadeCanvas', null)
  frameos.remember('win', null)
}

// The table once won, cards gone: empty places, and on each foundation what
// is left of it once `left` cards have left.
const tableParts = (t, table, left: number) => {
  const { cardW: w, cardH: h } = table
  const parts = table.places.map((p) => <Place t={t} x={p.x} y={p.y} w={w} h={h} />)
  table.piles.forEach((p, k) => {
    const card = pileTop(left, k)
    parts.push(card < 0 ? <Place t={t} x={p.x} y={p.y} w={w} h={h} suit={k} />
      : <Face t={t} card={card} x={p.x} y={p.y} w={w} h={h} full={true} lit={false} />)
  })
  return parts
}

const stampParts = (t, table, stamps) =>
  stamps.map((s) => <Face t={t} card={s.card} x={s.x} y={s.y} w={table.cardW} h={table.cardH} full={true} lit={false} />)

// The game is won. On a fast panel the cards fall into a canvas the app
// keeps, a few copies drawn over it a frame, so the trails cost nothing to
// keep: memory is the canvas, the screen's size, however long the cascade
// runs. On e-paper, one picture of it with the trails drawn.
const winScreen = (app, ui, t, game, gap: number, room = null) => {
  const geometry = tableOf(ui, gap, room)
  const table = { W: ui.W, H: ui.H, ...geometry }
  const win = cascadeOf(game)
  const banner = (
    <div className={`absolute ${room ? 'inset-x-[20%] top-[40%]' : 'inset-x-[18%] top-[7%]'} rounded-2xl p-[${ui.pad}px] flex flex-col items-center gap-[${ui.gap}px] ${t.banner}`}>
      <span className={`text-[${ui.title}px] font-bold`}>You won!</span>
      <span className={`text-[${ui.text}px]`}>{`In ${game.moves} moves`}</span>
      <Button ui={ui} className={`w-full ${t.primary}`} onClick={() => restart(app)}>Deal again</Button>
    </div>
  )
  if (!app.frame.fast) {
    setPace(app, IDLE)
    const steps = stepsUntilCard(win.seed, table, PAPER_CARD)
    const stamps = sampleCascade(win.seed, table, steps, PAPER_COPIES)
    return (
      <div className={`relative w-full h-full ${t.page}`} onClick={() => restart(app)}>
        <svg viewBox={`0 0 ${ui.W} ${ui.H}`} width={ui.W} height={ui.H}>
          {tableParts(t, table, PAPER_CARD + 1)}
          {stampParts(t, table, stamps)}
        </svg>
        {banner}
      </div>
    )
  }
  const canvas = frameos.canvas('cascade', ui.W, ui.H, t.felt)
  frameos.remember('cascadeCanvas', true)
  if (canvas.fresh) {
    // A new canvas, on the first frame or after the interpreter went: the table,
    // and what fell before in a few copies.
    frameos.draw(canvas, <g>{tableParts(t, table, win.c.n)}{stampParts(t, table, sampleCascade(win.seed, table, win.c.steps, REDRAW_COPIES))}</g>)
  }
  if (!win.over) {
    const stamps = []
    for (let i = 0; i < STEPS; i++) {
      const stamp = stepCascade(win.c, table)
      if (!stamp) break
      stamps.push(stamp)
    }
    if (stamps.length) frameos.draw(canvas, <g>{stampParts(t, table, stamps)}</g>)
    if (cascadeDone(win.c)) win.over = true
  }
  frameos.remember('win', win)
  setPace(app, win.over ? IDLE : PACE)
  return (
    <div className={`relative w-full h-full ${t.page}`} onClick={() => tapWin(app)}>
      <img className={`w-[${ui.W}px] h-[${ui.H}px]`} src={canvas} />
      {win.over ? banner : null}
    </div>
  )
}

// The sizes kept as one object while they stay the same: what the memo()'d
// components are given stays equal.
let steady = null
const steadyUi = (ui) => (steady && Object.keys(ui).every((key) => ui[key] === steady[key]) ? steady : (steady = ui))

export function get(app, context) {
  lastApp = app
  const ui = steadyUi(canvasOf(app, context))
  const t = highContrast(app) ? THEMES.high : THEMES.color
  const room = roundOf(context)

  if (frameos.recall('page') === 'options') {
    const rows = [{ field: 'draw', label: 'Draw from the stock', value: String(drawOf(app)), options: [['1', 'One card'], ['3', 'Three cards']] }]
    return <OptionsPage ui={ui} t={t} title="Solitaire" rows={rows} room={room}
      onClose={() => frameos.remember('page', null)} onNew={() => restart(app)} />
  }

  game = loadGame(app)
  if (!game) {
    game = deal(drawOf(app), Math.random)
    save(game)
  } else if (game.draw !== drawOf(app)) {
    // One or three from the stock may change in the middle of a game.
    game = { ...game, draw: drawOf(app) }
    save(game)
  }
  const gap = Math.max(4, Math.round(Math.min(ui.W, ui.H) * 0.014))
  if (won(game)) return winScreen(app, ui, t, game, gap, room)
  letCascadeGo(app)
  sync()

  if (room) {
    // Round: the classic table across the circle's middle, the moves in the
    // arc above it and the buttons in the arc below.
    const rt = roundTableOf(room, gap)
    const buttonH = Math.min(ui.button, 42)
    const buttonsTop = rt.bottom + gap + 2
    const buttonsW = Math.min(rt.tableW, room.chord(buttonsTop + buttonH - room.H / 2))
    return (
      <div className={`relative w-[${room.W}px] h-[${room.H}px] ${t.page}`}>
        <div className={`absolute left-0 top-[${rt.top - Math.round(ui.small * 1.5) - gap}px] w-[${room.W}px] flex justify-center`}>
          <RoundMoves ui={ui} t={t} />
        </div>
        <div className={`absolute left-[${rt.x0}px] top-[${rt.top}px] flex flex-col gap-[${gap}px]`}>
          <div className={`flex justify-between w-[${rt.tableW}px]`}>
            <StockWaste t={t} draw={game.draw} cardW={rt.cardW} cardH={rt.cardH} gap={gap} vertical={false} />
            <Foundations t={t} cardW={rt.cardW} cardH={rt.cardH} gap={gap} vertical={false} />
          </div>
          <Tableau t={t} cardW={rt.cardW} cardH={rt.cardH} gap={gap} height={rt.bottom - rt.top - rt.cardH - gap} />
        </div>
        <div className={`absolute left-0 top-[${buttonsTop}px] w-[${room.W}px] flex justify-center`}>
          <RoundButtons ui={ui} t={t} width={buttonsW} h={buttonH} gap={gap} />
        </div>
      </div>
    )
  }

  // Wide screens: stock and waste on the left, the columns, the foundations
  // on the right, all at full height. Tall and square ones: the classic
  // table, stock and foundations along the top.
  const { mode, wide, cardW, cardH } = sizesOf(ui, gap)
  if (mode === 'strip') {
    return (
      <div className={`flex w-full h-full p-[${ui.pad}px] gap-[${gap}px] justify-center ${t.page}`}>
        <StockWaste t={t} draw={game.draw} cardW={cardW} cardH={cardH} gap={gap} vertical={true} />
        <Tableau t={t} cardW={cardW} cardH={cardH} gap={gap} height={ui.H - ui.pad * 2} />
        <Foundations t={t} cardW={cardW} cardH={cardH} gap={gap} cols={2} />
        <div className={`w-[${stripColumnOf(ui)}px] h-full shrink-0 flex flex-col justify-end`}>
          <SideButtons ui={ui} t={t} cardW={stripColumnOf(ui)} gap={gap} />
        </div>
      </div>
    )
  }
  if (wide) {
    return (
      <div className={`flex w-full h-full p-[${ui.pad}px] gap-[${gap}px] justify-center ${t.page}`}>
        <div className={`w-[${cardW}px] h-full flex flex-col gap-[${gap}px]`}>
          <StockWaste t={t} draw={game.draw} cardW={cardW} cardH={cardH} gap={gap} vertical={true} />
          <div className="flex-1" />
          <SideButtons ui={ui} t={t} cardW={cardW} gap={gap} />
        </div>
        <Tableau t={t} cardW={cardW} cardH={cardH} gap={gap} height={ui.H - ui.pad * 2} />
        <Foundations t={t} cardW={cardW} cardH={cardH} gap={gap} vertical={true} />
      </div>
    )
  }
  const buttonsH = ui.button
  const tableW = cardW * 7 + gap * 6
  return (
    <div className={`flex flex-col w-full h-full p-[${ui.pad}px] gap-[${gap}px] items-center ${t.page}`}>
      <div className={`flex justify-between w-[${tableW}px]`}>
        <StockWaste t={t} draw={game.draw} cardW={cardW} cardH={cardH} gap={gap} vertical={false} />
        <Foundations t={t} cardW={cardW} cardH={cardH} gap={gap} vertical={false} />
      </div>
      <Tableau t={t} cardW={cardW} cardH={cardH} gap={gap}
        height={ui.H - ui.pad * 2 - cardH - buttonsH - gap * 2} />
      <ButtonRow ui={ui} t={t} width={tableW} gap={gap} />
    </div>
  )
}

