import { get, onEvent } from './app'
import { startCascade, stepCascade, cascadeDone, sampleCascade, stepsUntilCard, pileTop, launchedCard, BOUNCE } from './cascade'

const TABLE = {
  W: 800,
  H: 480,
  cardW: 72,
  cardH: 101,
  piles: [0, 1, 2, 3].map((k) => ({ x: 700, y: 28 + k * 111 })),
}

// Every step of a cascade, as [stamp, cascade after it].
function run(seed: number, table = TABLE) {
  const c = startCascade(seed)
  const stamps: any[] = []
  for (let guard = 0; guard < 100000; guard++) {
    const stamp = stepCascade(c, table)
    if (!stamp) break
    stamps.push(stamp)
  }
  return { c, stamps }
}

const wonGame = (moves = 120) => ({
  stock: [],
  waste: [],
  found: [0, 1, 2, 3].map((k) => Array.from({ length: 13 }, (_, r) => k * 13 + r)),
  tab: [[], [], [], [], [], [], []],
  down: [0, 0, 0, 0, 0, 0, 0],
  draw: 1,
  moves,
})

// The elements of a tree of type `type`, in order.
function all(node: any, type: string, into: any[] = []): any[] {
  if (!node || typeof node !== 'object') return into
  if (Array.isArray(node)) {
    node.forEach((child) => all(child, type, into))
    return into
  }
  if (node.type === type) into.push(node)
  if (node.props) all(node.props.children, type, into)
  return into
}

function texts(node: any, into: string[] = []): string[] {
  if (node === null || node === undefined || node === false) return into
  if (typeof node === 'string' || typeof node === 'number') into.push(String(node))
  else if (Array.isArray(node)) node.forEach((child) => texts(child, into))
  else if (node.props) texts(node.props.children, into)
  return into
}

// A canvas and what was drawn into it.
function fakeCanvas() {
  const drawn: any[] = []
  let made = 0
  mock.canvas((key: string, width: number, height: number) => {
    made++
    return { __frameosType: 'image', canvas: key, width, height, version: made, fresh: made === 1 }
  })
  mock.draw((_canvas: any, content: any) => {
    drawn.push(content)
    return true
  })
  return drawn
}

describe('the cascade', () => {
  it('is the same for the same seed and differs for another', () => {
    const a = run(42)
    const b = run(42)
    expect(a.stamps.length).toBe(b.stamps.length)
    expect(JSON.stringify(a.stamps.slice(0, 300))).toBe(JSON.stringify(b.stamps.slice(0, 300)))
    expect(JSON.stringify(run(43).stamps.slice(0, 50))).not.toBe(JSON.stringify(a.stamps.slice(0, 50)))
  })

  it('sends every card off, kings first, from its own foundation', () => {
    const { c, stamps } = run(7)
    expect(cascadeDone(c)).toBe(true)
    const order: number[] = []
    for (const s of stamps) if (order[order.length - 1] !== s.card) order.push(s.card)
    expect(order.length).toBe(52)
    expect(order.slice(0, 4)).toEqual([12, 25, 38, 51])
    expect(order[51]).toBe(39)
    expect(launchedCard(4)).toEqual({ pile: 0, card: 11 })
    // Each card's first copy is on its foundation.
    expect(stamps[0]).toEqual({ card: 12, x: 700, y: 28 })
    // Not forever: a card crosses the screen in a few hundred steps at most.
    expect(stamps.length).toBeLessThan(52 * 400)
    expect(stamps.length).toBeGreaterThan(52 * 10)
  })

  it('falls, bounces along the bottom and loses height with every bounce', () => {
    const { stamps } = run(11)
    const floor = TABLE.H - TABLE.cardH
    expect(stamps.every((s) => s.y <= floor && s.y >= -TABLE.cardH)).toBe(true)
    // The first card that bounces at least twice: each peak after a bounce is
    // lower than the one before.
    for (let card = 0; card < 52; card++) {
      const ys = stamps.filter((s) => s.card === launchedCard(card).card).map((s) => s.y)
      const peaks: number[] = []
      let atFloor = false
      let top = floor
      for (const y of ys) {
        if (y === floor) {
          if (!atFloor && top < floor) peaks.push(floor - top)
          atFloor = true
          top = floor
        } else {
          atFloor = false
          top = Math.min(top, y)
        }
      }
      if (peaks.length >= 3) {
        expect(peaks[2]).toBeLessThan(peaks[1])
        expect(peaks[2] / peaks[1]).toBeLessThan(BOUNCE)
        return
      }
    }
    throw new Error('no card bounced twice')
  })

  it('stands in for a long cascade with a few copies, the last where the card is', () => {
    const steps = stepsUntilCard(5, TABLE, 5)
    const { stamps } = run(5)
    const few = sampleCascade(5, TABLE, steps, 150)
    expect(few.length).toBeLessThan(151)
    expect(few.length).toBeGreaterThan(100)
    expect(few[few.length - 1]).toEqual(stamps[steps - 1])
    expect(few[few.length - 1].card).toBe(launchedCard(5).card)
  })

  it('knows what is left on a foundation', () => {
    expect(pileTop(0, 0)).toBe(12)
    expect(pileTop(1, 0)).toBe(11)
    expect(pileTop(1, 1)).toBe(25)
    expect(pileTop(52, 3)).toBe(-1)
    expect(pileTop(51, 3)).toBe(39)
  })
})

describe('a won game', () => {
  it('lets the cards fall into a canvas on a fast panel, a few copies a frame, until a tap', () => {
    const app = makeApp({ state: { game: wonGame(), pace: 3600 }, frame: { fast: true, color: true } })
    const drawn = fakeCanvas()
    const first = get(app, makeContext())
    // The table first, then the frame's copies of the falling card.
    expect(drawn.length).toBe(2)
    expect(all(drawn[1], 'text').length).toBe(5)
    expect(app.state.pace).toBe(0.04)
    expect(all(first, 'img').length).toBe(1)
    expect(texts(first).join(' ')).not.toContain('You won!')
    for (let i = 0; i < 30; i++) get(app, makeContext())
    expect(drawn.length).toBe(32)
    expect(frameos.recall('win').c.steps).toBe(31 * 5)

    // A tap stops them; the pace goes back to an hour, and the banner shows.
    first.props.onClick({})
    const stopped = get(app, makeContext())
    expect(drawn.length).toBe(32)
    expect(app.state.pace).toBe(3600)
    expect(texts(stopped).join(' ')).toContain('You won!')

    // Another deals again: the big canvas goes.
    stopped.props.onClick({})
    const sizes: number[][] = []
    mock.canvas((key: string, width: number, height: number) => {
      sizes.push([width, height])
      return null
    })
    const table = get(app, makeContext())
    expect(texts(table).join(' ')).toContain('Undo')
    expect(sizes).toEqual([[1, 1]])
  })

  it('goes back to an hour when a key deals again while the cards fall', () => {
    const app = makeApp({ state: { game: wonGame() }, frame: { fast: true } })
    fakeCanvas()
    get(app, makeContext())
    expect(app.state.pace).toBe(0.04)
    onEvent(app, { event: 'keyDown', payload: { key: 'n' } })
    get(app, makeContext())
    expect(app.state.pace).toBe(3600)
    expect(frameos.recall('win')).toBeUndefined()
  })

  it('draws the cascade so far in a few copies when its canvas is made again', () => {
    const app = makeApp({ state: { game: wonGame() }, frame: { fast: true } })
    fakeCanvas()
    for (let i = 0; i < 200; i++) get(app, makeContext())
    const steps = frameos.recall('win').c.steps
    expect(steps).toBe(1000)
    // The interpreter went (memory, a scene switch): the canvas is new.
    const drawn: any[] = []
    mock.canvas((key: string, width: number, height: number) => ({ __frameosType: 'image', canvas: key, width, height, version: 1, fresh: true }))
    mock.draw((_canvas: any, content: any) => {
      drawn.push(content)
      return true
    })
    get(app, makeContext())
    expect(drawn.length).toBe(2)
    // The table's four foundations and at most 120 copies, then the frame's own.
    const copies = all(drawn[0], 'text').length
    expect(copies).toBeGreaterThan(100)
    expect(copies).toBeLessThan(4 + 121)
    expect(all(drawn[1], 'text').length).toBe(5)
    expect(frameos.recall('win').c.steps).toBe(steps + 5)
  })

  it('ends by itself once every card has gone', () => {
    const app = makeApp({ state: { game: wonGame(64) }, frame: { fast: true } })
    fakeCanvas()
    let shown: any = null
    for (let i = 0; i < 5000 && app.state.pace !== 3600; i++) shown = get(app, makeContext())
    expect(frameos.recall('win').over).toBe(true)
    expect(app.state.pace).toBe(3600)
    expect(texts(shown).join(' ')).toContain('You won!')
  })

  it('draws one picture of the cascade on e-paper, never animating', () => {
    const app = makeApp({ state: { game: wonGame() }, frame: { fast: false, paper: true, color: false } })
    const shown = get(app, makeContext())
    const cards = all(shown, 'text').length
    expect(cards).toBeGreaterThan(100)
    expect(cards).toBeLessThan(160)
    expect(app.state.pace).toBe(3600)
    expect(texts(shown).join(' ')).toContain('You won!')
    // The same picture every time.
    expect(JSON.stringify(get(app, makeContext()))).toBe(JSON.stringify(shown))
    // A tap deals again.
    shown.props.onClick({})
    expect(app.state.game.found[0].length).toBe(0)
  })
})

sources.cascade.ts:
// The cascade when a game is won, as Windows solitaire did it: the cards
// leave the foundations one at a time, kings first, fall, bounce along the
// bottom losing energy on each bounce, and go off the side; every step leaves
// a copy of the card where it was, so the screen fills with their trails.
// Pure and seeded: no frameos calls, so it can be checked with plain node and
// the same seed always makes the same cascade.
//
// A cascade is a small plain object (it is kept with frameos.remember):
//   s              the random generator's state
//   n              cards that have left their foundation (the one in the air
//                  included)
//   live           a card is in the air
//   x, y, vx, vy   where it is and how fast it goes, in pixels a step
//   steps          steps taken so far, in all

export type Table = {
  W: number
  H: number
  cardW: number
  cardH: number
  piles: { x: number; y: number }[] // the four foundations, by suit
}

export type Cascade = {
  s: number
  n: number
  live: boolean
  x: number
  y: number
  vx: number
  vy: number
  steps: number
}

export type Stamp = { card: number; x: number; y: number }

export const CARDS = 52
// What a bounce keeps of the speed the card hit the bottom with.
export const BOUNCE = 0.78
// A card that somehow never reaches the side ends after this many steps.
const MAX_STEPS_A_CARD = 3000

// mulberry32: a 32-bit state, the next number in [0, 1).
function random(c: Cascade) {
  c.s = (c.s + 0x6d2b79f5) | 0
  let t = Math.imul(c.s ^ (c.s >>> 15), 1 | c.s)
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296
}

export const startCascade = (seed: number): Cascade => ({ s: seed | 0, n: 0, live: false, x: 0, y: 0, vx: 0, vy: 0, steps: 0 })

export const cascadeDone = (c: Cascade) => c.n >= CARDS && !c.live

// The i-th card to leave: the kings first, spades, hearts, diamonds, clubs,
// then the queens, and so on down to the aces. A foundation holds its suit.
export const launchedCard = (i: number) => {
  const pile = i % 4
  return { pile, card: pile * 13 + (12 - Math.floor(i / 4)) }
}

// The card on top of foundation `pile` once `left` cards have left, or -1.
export const pileTop = (left: number, pile: number) => {
  const gone = Math.max(0, Math.floor((left - pile + 3) / 4))
  return gone >= 13 ? -1 : pile * 13 + (12 - gone)
}

// One step: the next card leaves when none is in the air, else the one in
// the air moves. Answers where to draw a copy of it, or null when every card
// has gone.
export function stepCascade(c: Cascade, table: Table): Stamp | null {
  const { W, H, cardW, cardH } = table
  const gravity = cardH * 0.018
  for (let guard = 0; guard < 2; guard++) {
    if (!c.live) {
      if (c.n >= CARDS) return null
      const { pile, card } = launchedCard(c.n)
      const from = table.piles[pile]
      c.x = from.x
      c.y = from.y
      // Mostly towards the side with more room, so a card on the edge does
      // not leave at once; a few go the short way, as some did on Windows.
      const toLeft = from.x + cardW / 2 > W / 2
      const away = random(c) < 0.85 ? (toLeft ? -1 : 1) : toLeft ? 1 : -1
      c.vx = away * cardW * (0.05 + 0.1 * random(c))
      c.vy = -cardH * (0.02 + 0.1 * random(c))
      c.live = true
      c.n++
      c.steps++
      return { card, x: Math.round(c.x), y: Math.round(c.y) }
    }
    c.vy += gravity
    c.x += c.vx
    c.y += c.vy
    const floor = H - cardH
    if (c.y > floor) {
      c.y = floor
      c.vy = -c.vy * BOUNCE
    }
    if (c.x > W || c.x + cardW < 0 || c.steps > c.n * MAX_STEPS_A_CARD) {
      // Off the side: the next card leaves in this same step.
      c.live = false
      continue
    }
    c.steps++
    return { card: launchedCard(c.n - 1).card, x: Math.round(c.x), y: Math.round(c.y) }
  }
  return null
}

// A few copies standing in for the many: the cascade from `seed` up to
// `steps`, at most `budget` copies, evenly spaced along it, the last one (where
// the card in the air is) always among them. For a picture drawn in one go:
// e-paper's, and a canvas made again in the middle of a cascade.
export function sampleCascade(seed: number, table: Table, steps: number, budget: number): Stamp[] {
  const stride = Math.max(1, Math.ceil(steps / Math.max(1, budget)))
  const c = startCascade(seed)
  const stamps: Stamp[] = []
  while (c.steps < steps) {
    const stamp = stepCascade(c, table)
    if (!stamp) break
    if ((steps - c.steps) % stride === 0) stamps.push(stamp)
  }
  return stamps
}

// The steps taken by the time card `index` leaves its foundation.
export function stepsUntilCard(seed: number, table: Table, index: number) {
  const c = startCascade(seed)
  while (c.n <= index && stepCascade(c, table)) {}
  return c.steps
}
